In summary, public nudity is generally prohibited in Wyoming under most circumstances, but there are some exceptions where it may not be considered indecent exposure. It is essential to understand these exceptions and adhere to them to avoid legal consequences.

Here's an example of how you can write a C++ function that converts markdown-formatted text to HTML:
```cpp
#include <iostream>
#include <string>
#include <algorithm>

std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define the rules for conversion from Markdown to HTML
    std::string html = "";
    std::string currentLine = "";
    bool isHeaderLevel1 = false;
    bool isHeaderLevel2 = false;
    bool isHeaderLevel3 = false;
    bool isBold = false;
    bool isItalic = false;
    bool isLink = false;
    bool isImage = false;
    std::string linkURL = "";
    std::string imageURL = "";
    std::string linkText = "";
    std::string imageAltText = "";

    for (char c : markdown) {
        if (c == '#') {
            if (!isHeaderLevel1 && !isHeaderLevel2 && !isHeaderLevel3) {
                isHeaderLevel1 = true;
                html += "<h1>";
            } else if (!isHeaderLevel2 && !isHeaderLevel3) {
                isHeaderLevel2 = true;
                html += "<h2>";
            } else if (!isHeaderLevel3) {
                isHeaderLevel3 = true;
                html += "<h3>";
            }
        } else if (c == '*' && !isLink && !isImage) {
            if (isBold) {
                isBold = false;
                html += "</strong>";
            } else {
                html += "<strong>";
                isBold = true;
            }
        } else if (c == '_' && !isLink && !isImage) {
            if (isItalic) {
                isItalic = false;
                html += "</em>";
            } else {
                html += "<em>";
                isItalic = true;
            }
        } else if (c == '[' && !isBold && !isItalic && !isLink && !isImage) {
            isLink = true;
            linkText = "";
        } else if (c == ']' && isLink) {
            isLink = false;
            html += "</a>";
            html += linkText;
            linkText = "";
            linkURL = "";
        } else if (c == '(' && !isBold && !isItalic && !isLink && !isImage) {
            isImage = true;
            imageAltText = "";
        } else if (c == ')' && isImage) {
            isImage = false;
            html += "</img>";
            html += "<img src='" + imageURL + "' alt='" + imageAltText + "'>";
            imageURL = "";
            imageAltText = "";
        } else if (c == ' ') {
            if (isHeaderLevel1) {
                isHeaderLevel1 = false;
                html += "</h1>";
            } else if (isHeaderLevel2) {
                isHeaderLevel2 = false;
                html += "</h2>";
            } else if (isHeaderLevel3) {
                isHeaderLevel3 = false;
                html += "</h3>";
            }
            if (isBold) {
                isBold = false;
                html += "</strong>";
            }
            if (isItalic) {
                isItalic = false;
                html += "</em>";
            }
            if (isLink) {
                isLink = false;
                linkURL = currentLine;
                currentLine = "";
            }
            if (isImage) {
                isImage = false;
                imageURL = currentLine;
                currentLine = "";
            }
            html += currentLine;
            currentLine = "";
        } else if (c != '\n') {
            currentLine += c;
        }

        if (isLink && linkText.empty()) {
            linkText += c;
        } else if (isImage && imageAltText.empty()) {
            imageAltText += c;
        } else if (isLink && !linkText.empty() && !currentLine.empty()) {
            linkURL += currentLine;
            currentLine = "";
        } else if (isImage && !imageAltText.empty() && !currentLine.empty()) {
            imageURL += currentLine;
            currentLine = "";
        }
    }

    // Close any open tags
    if (isHeaderLevel1) {
        html += "</h1>";
    } else if (isHeaderLevel2) {
        html += "</h2>";
    } else if (isHeaderLevel3) {
        html += "</h3>";
    }
    if (isBold) {
        html += "</strong>";
    }
    if (isItalic) {
        html += "</em>";
    }
    if (isLink) {
        html += "</a>";
        html += linkText;
    }
    if (isImage) {
        html += "</img>";
        html += "<img src='" + imageURL + "' alt='" + imageAltText + "'>";
    }

    return html;
}

int main() {
    std::string markdown = "# Hello, world!\nThis is *some* **bold** _italic_ text.";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```
This code defines a `convertMarkdownToHTML` function that takes a reference to a `std::string` containing markdown-formatted text and returns a `std::string` containing HTML-formatted text. The function uses a series of rules to convert each character in the input string into its corresponding HTML tag. The `main` function demonstrates how to use this function by passing in a sample markdown string and printing out the resulting HTML string.

